// Cards live in the Next.js flight payload (self.__next_f.push chunks), not in plain HTML:
// the visible markup only shows 3 tags + "+N", the payload has the full list and the raw image URL.
const decodeFlightRows = (html) => {
  const chunks = [...html.matchAll(/self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g)];
  const flight = chunks.map(m => JSON.parse('"' + m[1] + '"')).join('');
  const utf8Bytes = (cp) => cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
  const rows = {};
  let pos = 0;
  while (pos < flight.length) {
    const colon = flight.indexOf(':', pos);
    if (colon < 0) break;
    const id = flight.slice(pos, colon);
    // "id:T<hex byte length>,<text>" rows carry raw text with no trailing newline
    const textRow = flight.slice(colon + 1).match(/^T([0-9a-f]+),/);
    if (textRow) {
      let bytes = parseInt(textRow[1], 16);
      let end = colon + 1 + textRow[0].length;
      while (bytes > 0 && end < flight.length) {
        const cp = flight.codePointAt(end);
        bytes -= utf8Bytes(cp);
        end += cp > 0xffff ? 2 : 1;
      }
      pos = end;
      continue;
    }
    let newline = flight.indexOf('\n', colon);
    if (newline < 0) newline = flight.length;
    const payload = flight.slice(colon + 1, newline);
    if (/^[0-9a-f]+$/.test(id) && (payload[0] === '[' || payload[0] === '{')) {
      try { rows[id] = JSON.parse(payload); } catch (e) { /* not a JSON row */ }
    }
    pos = newline + 1;
  }
  return rows;
};

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const REF = /^\$L([0-9a-f]+)$/;

// First href / image / name / tags under one card. "$L<id>" strings point at streamed rows.
const readCard = (node, card, rows) => {
  if (typeof node === 'string') {
    const ref = node.match(REF);
    if (ref && rows[ref[1]] && !card.seen.has(ref[1])) { card.seen.add(ref[1]); readCard(rows[ref[1]], card, rows); }
    return card;
  }
  if (!Array.isArray(node)) return card;
  if (node[0] === '$' && node[3] && typeof node[3] === 'object') {
    const props = node[3];
    if (!card.path && typeof props.href === 'string' && props.href.startsWith('/campaigns/')) card.path = props.href;
    if (!card.image_url && typeof props.src === 'string') { card.image_url = props.src; card.campaign_title = props.alt || ''; }
    if (!card.game_name && node[1] === 'p' && typeof props.children === 'string') card.game_name = props.children;
    if (!card.tags && Array.isArray(props.tags)) card.tags = props.tags.map(t => t.name);
    readCard(props.children, card, rows);
  } else {
    for (const child of node) readCard(child, card, rows);
  }
  return card;
};

// A card is a React element keyed by the campaign UUID that links to /campaigns/...
const findCards = (node, out, rows) => {
  if (!Array.isArray(node)) return;
  if (node[0] === '$' && typeof node[2] === 'string' && UUID.test(node[2])) {
    const card = readCard(node, { campaign_id: node[2], seen: new Set() }, rows);
    if (card.path) { out.push(card); return; }
  }
  for (const child of node) {
    if (Array.isArray(child)) findCards(child, out, rows);
    else if (child && typeof child === 'object' && child.children) findCards([child.children], out, rows);
  }
};

const campaigns = new Map();
for (const page of $input.all()) {
  const rows = decodeFlightRows(page.json.data || '');
  const cards = [];
  for (const row of Object.values(rows)) findCards(row, cards, rows);
  for (const card of cards) if (!campaigns.has(card.campaign_id)) campaigns.set(card.campaign_id, card);
}

if (campaigns.size === 0) {
  throw new Error('No campaigns found on jestr.gg/campaigns. The page structure has probably changed; the parser in this node needs updating.');
}

const alreadyLogged = new Set(
  $('READ CAMPAIGNS ALREADY LOGGED').all().map(row => String(row.json.campaign_id || '').trim()).filter(Boolean)
);

return [...campaigns.values()]
  .filter(card => !alreadyLogged.has(card.campaign_id))
  .map(card => ({
    json: {
      campaign_id: card.campaign_id,
      game_name: card.game_name || '',
      campaign_title: card.campaign_title || '',
      campaign_url: 'https://www.jestr.gg' + card.path,
      image_url: card.image_url || '',
      tags: (card.tags || []).join(', '),
    },
  }));

// The detail page's flight payload carries a full `campaign` object (dates, studio, links)
// that the listing card does not show.
const decodeFlightRows = (html) => {
  const chunks = [...html.matchAll(/self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g)];
  const flight = chunks.map(m => JSON.parse('"' + m[1] + '"')).join('');
  const utf8Bytes = (cp) => cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
  const rows = {};
  let pos = 0;
  while (pos < flight.length) {
    const colon = flight.indexOf(':', pos);
    if (colon < 0) break;
    const id = flight.slice(pos, colon);
    // "id:T<hex byte length>,<text>" rows carry raw text with no trailing newline
    const textRow = flight.slice(colon + 1).match(/^T([0-9a-f]+),/);
    if (textRow) {
      let bytes = parseInt(textRow[1], 16);
      let end = colon + 1 + textRow[0].length;
      while (bytes > 0 && end < flight.length) {
        const cp = flight.codePointAt(end);
        bytes -= utf8Bytes(cp);
        end += cp > 0xffff ? 2 : 1;
      }
      pos = end;
      continue;
    }
    let newline = flight.indexOf('\n', colon);
    if (newline < 0) newline = flight.length;
    const payload = flight.slice(colon + 1, newline);
    if (/^[0-9a-f]+$/.test(id) && (payload[0] === '[' || payload[0] === '{')) {
      try { rows[id] = JSON.parse(payload); } catch (e) { /* not a JSON row */ }
    }
    pos = newline + 1;
  }
  return rows;
};

const findCampaign = (node, id) => {
  if (!node || typeof node !== 'object') return null;
  if (node.campaign && typeof node.campaign === 'object' && node.campaign.id === id) return node.campaign;
  for (const value of Object.values(node)) {
    const found = findCampaign(value, id);
    if (found) return found;
  }
  return null;
};

const linkList = (links) => Object.entries(links || {})
  .filter(([, url]) => typeof url === 'string' && url)
  .map(([site, url]) => site + ': ' + url)
  .join('\n');

// "2026-09-22 21:00:00+00" -> "2026-09-22 21:00" (column header says UTC)
const utc = (value) => typeof value === 'string' ? value.replace(/:\d{2}(\.\d+)?\+00$/, '') : '';
const text = (value) => typeof value === 'string' && !value.startsWith('$') ? value : '';

const firstSeen = $now.toFormat('yyyy-MM-dd HH:mm');
const out = [];
let parsed = 0;

for (let i = 0; i < $input.all().length; i++) {
  const listing = $('EXTRACT NEW CAMPAIGNS FROM LISTING').itemMatching(i).json;
  const detail = findCampaign(Object.values(decodeFlightRows($input.all()[i].json.data || '')), listing.campaign_id) || {};
  if (detail.id) parsed++;
  out.push({
    json: {
      campaign_id: listing.campaign_id,
      first_seen_at: firstSeen,
      game_name: listing.game_name || text(detail.game_title),
      campaign_title: listing.campaign_title || text(detail.title),
      campaign_url: listing.campaign_url,
      image_url: listing.image_url || text(detail.thumbnail_url),
      tags: listing.tags,
      start_date_utc: utc(detail.start_date),
      end_date_utc: utc(detail.end_date),
      description: text(detail.description),
      developers: (detail.developers || []).join(', '),
      publishers: (detail.publishers || []).join(', '),
      store_links: linkList(detail.store_links),
      igdb_url: text(detail.igdb_url),
      social_links: linkList(detail.social_links),
      trailer_url: text(detail.trailer),
      background_image_url: text(detail.background_image),
      uses_ai_generated_content: detail.id ? (detail.uses_ai_generated_content ? 'yes' : 'no') : '',
      ai_disclosure: text(detail.ai_disclosure),
      details_found: detail.id ? 'yes' : 'no',
    },
    pairedItem: { item: i },
  });
}

if (out.length > 0 && parsed === 0) {
  throw new Error('No campaign details could be read from any detail page. The page structure has probably changed; the parser in this node needs updating.');
}

return out;
